CREATE OR REPLACE FUNCTION lead_private.ml_list(_offset integer DEFAULT 0,_limit integer DEFAULT 200) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Anmeldung erforderlich' USING ERRCODE='42501'; END IF;
 IF _offset<0 OR _limit<1 OR _limit>200 THEN RAISE EXCEPTION 'Ungültige Seitengröße'; END IF;
 RETURN coalesce((SELECT jsonb_agg(x.row) FROM(SELECT to_jsonb(l)-'metadata' || jsonb_build_object('workspace',coalesce(l.metadata->'lead_workspace','{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object('last_activity_at',coalesce(l.metadata->'lead_workspace'->>'last_activity_at',(SELECT max(h.created_at)::text FROM public.sales_lead_history h WHERE h.lead_id=l.id AND h.action IN ('contact_activity','call','email_sent','whatsapp_sent','meeting'))))), 'followups',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM public.sales_followups f WHERE f.lead_id=l.id),'[]'::jsonb)) AS row FROM public.sales_leads l WHERE public.ml_can_access(l.id) ORDER BY l.created_at DESC,l.id OFFSET _offset LIMIT _limit)x),'[]'::jsonb);
 END $$;
CREATE OR REPLACE FUNCTION lead_private.ml_order_status(_lead_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.ml_can_access(_lead_id) THEN RAISE EXCEPTION 'Lead nicht zugänglich' USING ERRCODE='42501'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'order_number',o.order_number,'order_date',o.order_date,'total_amount',o.total_amount,'order_status',o.order_status,'source_system',o.source_system,'payment_status',o.finance_payment_status,'paid_amount',o.finance_paid_amount,'delivery_status',o.order_status)) FROM public.orders o WHERE EXISTS(SELECT 1 FROM public.sales_leads l JOIN public.offers f ON (f.id=l.converted_offer_id OR f.payload->>'lead_id'=l.id::text) WHERE l.id=_lead_id AND (o.raw_data->>'offer_number'=f.offer_number OR o.raw_data->>'source_offer'=f.offer_number OR o.raw_data->>'source_offer_number'=f.offer_number))),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION lead_private.ml_order_status(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION lead_private.ml_order_status(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.ml_detail(_lead_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT lead_private.ml_detail(_lead_id)||jsonb_build_object('orders',lead_private.ml_order_status(_lead_id)) $$;